int main(int argc,const char **argv){@autoreleasepool{if(argc!=7)return 2;NSImage *img=[[NSImage alloc]initWithContentsOfFile:@(argv[1])];if(!img)return 3;CGImageRef image=[img CGImageForProposedRect:NULL context:nil hints:nil];double w=CGImageGetWidth(image),h=CGImageGetHeight(image);CGRect r=CGRectMake(atof(argv[3])*w,atof(argv[4])*h,atof(argv[5])*w,atof(argv[6])*h);CGImageRef cropped=CGImageCreateWithImageInRect(image,r);if(!cropped)return 4;NSBitmapImageRep *rep=[[NSBitmapImageRep alloc]initWithCGImage:cropped];BOOL ok=[[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}]writeToFile:@(argv[2]) atomically:YES];CGImageRelease(cropped);return ok?0:5;}}
